SELECT id, subject_type, symbol, interval_code, candle_open_time, status, failure_reason, attempt_count, last_observation, late_live_close_at, resolved_at, created_at FROM local_reconciliation_audit WHERE created_at BETWEEN '2026-10-11 20:50:00' AND '2026-10-12 10:10:00' AND (symbol IN ('ACEUSDT','SHIBUSDT','DOGEUSDT','XRPUSDT','EGLDUSDT') OR symbol IS NULL) ORDER BY created_at LIMIT 100